INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('lis', 9, NULL, 'def gen():
    _s = [664106373]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 1000000000
    MODE = 0
    N = 200000
    if MODE == 1:
        a = [i * 3 + r(0, 2) for i in range(N)]
    elif MODE == 2:
        a = [r(-V, V) for _ in range(N)]
        a.sort(reverse=True)
    else:
        a = [r(-V, V) for _ in range(N)]
    return f"{N}\n{'' ''.join(map(str, a))}\n"
', '878', 0);
